#!/usr/bin/env python3
"""news-image-20261120 entry: the world news of 20 November 2026 in one image.

A light "morning paper" magazine cover: masthead, one hero story (the
International Court of Justice ruling that Myanmar committed genocide
against the Rohingya) and six more stories in a 2x3 grid -- a Houthi
missile hitting Riyadh's tallest tower, Anthropic's shares soaring on
their Nasdaq debut as markets slide, the Kerch Bridge hit a third time,
COP31's deadline nearing in Antalya, Trump returning from China, and
four nations demanding Gaza aid access. Every illustration is original
flat art drawn with PIL; all on-image text is rendered with PIL, so
every word is spelled correctly. The image is embedded below
(zlib-compressed, base64, palette-quantised to 256 colours to keep it
small), so this program needs nothing but the Python standard library,
no network and no files beside itself. Decoding fixed bytes is fully
deterministic: every run writes byte-identical output.
"""

import base64
import os
import zlib

_IMAGE_B64 = ""


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    image = zlib.decompress(base64.b64decode(_IMAGE_B64))
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(image)


if __name__ == "__main__":
    main()
